import{_ as t,a,c as r,ac as i}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"Rust Tokio 完整工程：有界任务、保序与失败收拢 · 输入与依赖至手工预期与恢复","description":"用真实输入求和连接任务所有权、JoinSet容量与可观察清理。","frontmatter":{"title":"Rust Tokio 完整工程：有界任务、保序与失败收拢 · 输入与依赖至手工预期与恢复","description":"用真实输入求和连接任务所有权、JoinSet容量与可观察清理。","splitFrom":"programming/rust/plus/practice/async-application.md","showdocs":{"topics":[{"id":"rust","title":"Rust","link":"/topics/rust/"}],"kind":"开发实践","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Rust Tokio 完整工程：有界任务、保序与失败收拢","summary":"用真实输入求和连接任务所有权、JoinSet容量与可观察清理。","status":"active","related":[{"title":"Rust 操作与命令","link":"/programming/rust/plus/ecosystem/rust-general-general","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 安装命令工具与发布软件包","link":"/programming/rust/plus/ecosystem/rust-general-general-part-04","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 编译、运行、测试与基准测量至阅读文档与命令帮助","link":"/programming/rust/plus/ecosystem/rust-general-general-part-03","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 查看、安装与更新 Rust 工具链至创建和定位 Cargo 项目","link":"/programming/rust/plus/ecosystem/rust-general-general-part-01","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 选择依赖、更新锁文件与准备离线构建至格式化、静态检查与自动修复","link":"/programming/rust/plus/ecosystem/rust-general-general-part-02","kind":"排错","scope":"general","audience":"general"}],"prev":{"text":"Rust Tokio 完整工程：有界任务、保序与失败收拢","link":"/programming/rust/plus/practice/async-application"},"next":{"text":"Rust Tokio 完整工程：有界任务、保序与失败收拢 · 全部同源工程文件至来源","link":"/programming/rust/plus/practice/async-application-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Rust Tokio 完整工程：有界任务、保序与失败收拢","link":"/programming/rust/plus/practice/async-application"},"next":{"text":"Rust Tokio 完整工程：有界任务、保序与失败收拢 · 全部同源工程文件至来源","link":"/programming/rust/plus/practice/async-application-part-02"}},"headers":[],"relativePath":"programming/rust/plus/practice/async-application-part-01.md","filePath":"programming/rust/plus/practice/async-application-part-01.md"}'),o={name:"programming/rust/plus/practice/async-application-part-01.md"};function n(s,e,c,l,p,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="rust-tokio-完整工程-有界任务、保序与失败收拢-·-输入与依赖至手工预期与恢复" tabindex="-1">Rust Tokio 完整工程：有界任务、保序与失败收拢 · 输入与依赖至手工预期与恢复 <a class="header-anchor" href="#rust-tokio-完整工程-有界任务、保序与失败收拢-·-输入与依赖至手工预期与恢复" aria-label="Permalink to &quot;Rust Tokio 完整工程：有界任务、保序与失败收拢 · 输入与依赖至手工预期与恢复&quot;">​</a></h1><p><a href="/programming/rust/plus/practice/async-application">返回分篇目录</a></p><p>先读<a href="/programming/rust/async-lifecycle#part-1">任务所有权和取消</a>。<code>examples/rust/p2-async-runtime</code> 为每行整数提交一个任务，使用 <code>checked_add</code> 汇总。提交数量、完成顺序、输出顺序分别受不同规则约束，观察时可分别记录。</p><h2 id="rust-tokio-完整工程-有界任务、保序与失败收拢" tabindex="-1">Rust Tokio 完整工程：有界任务、保序与失败收拢 <a class="header-anchor" href="#rust-tokio-完整工程-有界任务、保序与失败收拢" aria-label="Permalink to &quot;Rust Tokio 完整工程：有界任务、保序与失败收拢 {#rust-tokio-完整工程-有界任务、保序与失败收拢}&quot;">​</a></h2><p>先读<a href="/programming/rust/async-lifecycle#part-1">任务所有权和取消</a>。<code>examples/rust/p2-async-runtime</code> 为每行整数提交一个任务，使用 <code>checked_add</code> 汇总。提交数量、完成顺序、输出顺序分别受不同规则约束，观察时可分别记录。</p><h2 id="input-contract" tabindex="-1">输入与依赖 <a class="header-anchor" href="#input-contract" aria-label="Permalink to &quot;输入与依赖 {#input-contract}&quot;">​</a></h2><p>Rust异步工程输入契约定义每行任务与失败分层：UTF-8 每行空白分隔 u64，空行结果0，空文件无输出；CRLF 可用。单行 ERR 解析为故意拒绝的任务，非法数字则在提交前拒绝。checked_add 检测溢出，不依靠 debug/release 模式差异决定业务正确性。</p><p>固定 Tokio =1.48.0，edition 2021，声明 rust-version 1.71；MSRV 对齐依赖声明，不代表已经最低版本编译。rt-multi-thread 提供两线程 Runtime，macros 为测试属性服务，sync 为 oneshot 取消测试服务；无网络、fs、time 特性。同步 fs::read_to_string 在进入 Runtime 前完成，输入与结果 O(n) 驻内存；这是有限批次实验，不是恒定内存流处理器。示例源码未提交 Cargo.lock，首次构建会在工作区生成锁文件。具体依赖见下方同源文件。</p><h2 id="bounded-joinset" tabindex="-1">有界提交与保序 <a class="header-anchor" href="#bounded-joinset" aria-label="Permalink to &quot;有界提交与保序 {#bounded-joinset}&quot;">​</a></h2><p>Rust JoinSet有界保序依靠容量限制与输入序号：仅当 JoinSet.len 小于 limit 时提交下一个任务，回收后才补充。即使某任务已完成但未回收，也仍占一个容量槽。每任务每64项计算后 yield，结果不是 sleep 后伪造，也不依赖定时器或网络状态。</p><p>完成顺序由调度决定，join_next 返回完成的任务，不承诺输入顺序。每次提交携带 index，成功回写 results[index]，全部成功后 CLI 才统一按序打印。limit=0 先拒绝；limit 大于任务数不会凭空生成任务。worker_threads(2) 与 limit 分别限制线程数和跟踪任务数，两者不是同一指标。<a href="https://docs.rs/tokio/1.48.0/tokio/task/struct.JoinSet.html" target="_blank" rel="noopener noreferrer">JoinSet 1.48.0</a> 是接口依据。</p><h2 id="failure-drain" tabindex="-1">失败收拢与清理 <a class="header-anchor" href="#failure-drain" aria-label="Permalink to &quot;失败收拢与清理 {#failure-drain}&quot;">​</a></h2><p>Rust异步失败收拢遵循停止补充与等待退出：一旦观察业务 Err 或 JoinError，调度器不再读取 pending 任务，abort_all 请求其他任务取消，然后 join_next 直到集合为空，最后返回 Err。已完成但尚未观察的任务可能已产生结果；本工程无外部写入，整体失败时丢弃这些部分结果即可。</p><p>Metrics 的 Active guard 进入计算时递增、Drop 时递减；返回后 active=0 用来检验清理。oneshot 取消测试先确认任务已经进入，再 abort 和 join，避免 sleep 猜时序。它验证的是显式等待到返回的协议；上层直接取消 analyze 不享有同步等完析构保证。abort 对已启动 spawn_blocking 的同步代码不具备停止能力，所以没有把同步阻塞套一层 async 冒充可取消。</p><h2 id="expected-recovery" tabindex="-1">手工预期与恢复 <a class="header-anchor" href="#expected-recovery" aria-label="Permalink to &quot;手工预期与恢复 {#expected-recovery}&quot;">​</a></h2><p>Rust异步手工预期与恢复以整批结果为单位：normal.txt 依次输出6、7、4并退出0；reject.txt 报 rejected job，overflow.txt 报 sum overflow，invalid.txt 报 invalid u64，所有失败向 stderr 输出错误、退出1且无部分 stdout。缺文件和零上限也应失败；系统文件错误文本不作跨平台逐字承诺。</p><p>Linux x86_64 上使用 Rust/Cargo 1.93.1 与 Tokio 1.48.0 运行 <code>cargo test --workspace</code>，1 项单元测试与 5 项行为测试通过。执行 <code>cargo run -- inputs/normal.txt 2</code> 依次得到 6、7、4。Windows 和 macOS 示例未执行，最低编译器版本未测试。依赖缓存齐全后可加 <code>--offline</code> 复核。</p>',17)])])}const g=t(o,[["render",n]]);export{m as __pageData,g as default};
